contracts/JPSGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;


import "@openzeppelin/contracts/access/Ownable.sol";
import "./base/ERC4671.sol";

// Contract elements should be laid out in the following order:
// [Pragma] => [Import] => [Events] => [Errors] => [Interfaces] => [Libraries] => [Contracts]

// Inside each contract, library or interface, use the following order:
// [Type declarations] => [State variables] => [Events] => [Errors] => [Modifiers] => [Functions]

/**
 * @title JPSGuard
 * @dev JPSGuard is a smart contract that manages services and the minting of associated tokens.
 * 
 * This contract allows the owner to register different services, each of which can have its own 
 * parameters such as a price, a manager, and a status indicating its availability. Services can 
 * be public, private, service-specific, paid, or whitelisted.
 * 
 * Key features of the contract include:
 * 
 * - **Service Management**: The contract allows the owner to create and manage multiple services,
 *   each identified by a unique service ID. Each service has attributes such as:
 *   - URI for additional information.
 *   - Address of the manager responsible for the service.
 *   - Price for accessing the service (only for Paid Services).
 *   - Number of remaining tokens available for minting (If service has limited tokens).
 *   - Status indicating whether the service is public, private, etc.
 *   - Flags for limited tokens and active status.
 * 
 * - **Token Minting**: The contract provides various functions to mint tokens based on the 
 *   service's status. Tokens can be minted for:
 *   - Public access
 *   - Private access (only by the owner)
 *   - Specific services by authorized managers
 *   - Paid services, where the payment is processed and fees are handled
 *   - Whitelisted users
 * 
 * - **Whitelisting**: The contract supports a whitelisting mechanism to restrict access to certain
 *   services. Managers can update the whitelist status for users.
 * 
 * - **Error Handling**: The contract utilizes custom errors to provide efficient error handling
 *   and clear feedback when conditions are not met.
 * 
 * - **Ownership and Security**: Leveraging OpenZeppelin's Ownable contract, the owner has the
 *   authority to perform critical actions, ensuring secure management of services.
 * 
 * - **Withdrawals**: The owner can withdraw the contract's balance, ensuring control over 
 *   collected fees from paid services.
 * 
 * This contract is designed to provide a flexible framework for managing services and minting 
 * tokens while ensuring security and efficiency in interactions.
 */
contract JPSGuard is ERC4671, Ownable {
        enum ServiceStatus {
        Public,
        Private,
        Service,
        Paid,
        Whitelisted
    }

    struct Service {
        string uri;
        address manager;
        uint256 price;
        uint64 remainingTokens;
        ServiceStatus status;
        bool isLimitedToken;
        bool active;
    }

    uint256 public serviceCount;
    uint256 public immutable i_Transaction_Fee;

    mapping(address => uint256[]) public tokenIds;  // user address => token list
    mapping(uint256 => Service) public services;    // Service ID => Service Info
    mapping(uint256 => uint256) public serviceIds;  // token ID => service ID

    mapping(uint256 => mapping(address => bool)) public isWhitelisted;

    /* Events */
    event TokenMinted(address indexed _owner, uint256 indexed _tokenId);

    event ServiceRegistered(
        string uri,
        address indexed manager,
        uint256 price,
        uint256 indexed serviceID,
        uint64 indexed remainingTokens,
        ServiceStatus status,
        bool isLimitedToken,
        bool isPrivate
    );

    /* Errors */
    error JPSG_NotManager();
    error JPSG_NotTokenOwner();
    error JPSG_EmptyURI();
    error JPSG_InactiveToken();
    error JPSG_InvalidServiceID();
    error JPSG_InvalidTokenId();
    error JPSG_NotWhitelistedToken();
    error JPSG_NotWhitelisted();
    error JPSG_InsufficientFundsSent();
    error JPSG_TokenLimitExceeded();


    /* Modifiers */

    /**
     * @dev Modifier that checks if the caller is the manager of a specific service.
     * @param _serviceId The ID of the service to check.
     */
    modifier onlyManager(uint256 _serviceId) {
        require(services[_serviceId].manager == msg.sender, JPSG_NotManager());
        _;
    }

    /**
     * @dev Modifier that checks if a URI is non-empty.
     * @param _uri The URI to validate.
     */
    modifier nonEmptyURI(string memory _uri) {
        require(bytes(_uri).length > 0, JPSG_EmptyURI());
        _;
    }    

    /**
     * @dev Modifier that checks if the service ID is valid.
     * @param _serviceId The ID of the service to validate.
     */
    modifier checkServiceID(uint256 _serviceId) {
        require(_serviceId <= serviceCount, JPSG_InvalidServiceID());
        _;
    }

    /**
    * @dev Modifier that checks the status of a service.
    * @param _serviceId The ID of the service to check.
    * @param _status The expected status of the service.
    */
    modifier checkService(
        uint256 _serviceId,
        ServiceStatus _status
    ) {
        require(_serviceId <= serviceCount, JPSG_InvalidServiceID());
        require(services[_serviceId].active, JPSG_NotManager());
        require(services[_serviceId].status == _status, JPSG_InvalidTokenId());
        _;
    }

    /**
    * @dev Contract constructor that initializes the contract.
    * @param _uri The initial URI for the service.
    * @param _txFee The transaction fee percentage.
    */
    constructor(
        string memory _uri,
        uint8 _txFee
    ) Ownable(msg.sender) ERC4671("JPS", "JP Stacker Guard") {
        i_Transaction_Fee = _txFee;
        registerService(
            _uri,
            msg.sender,
            0,
            0,
            ServiceStatus.Public,
            false,
            true
        );
    }

    /**
    * @dev Registers a new service token.
    * @param _uri The URI for the service.
    * @param _manager The address of the service manager.
    * @param _price The price of the service.
    * @param _tokenCount The number of tokens available for the service.
    * @param _status The initial status of the service.
    * @param _isLimitedToken Indicates if the service has a token limit.
    * @param _active Indicates if the service is active.
    * @return The ID of the newly registered service.
    */
    function registerService(
        string memory _uri,
        address _manager,
        uint256 _price,
        uint64 _tokenCount,
        ServiceStatus _status,
        bool _isLimitedToken,
        bool _active
    ) public onlyOwner nonEmptyURI(_uri) returns (uint256) {
        serviceCount++;
        services[serviceCount] = Service(
            _uri,
            _manager,
            _price,
            _tokenCount,
            _status,
            _isLimitedToken,
            _active
        );
        emit ServiceRegistered(
            _uri,
            _manager,
            _price,
            serviceCount,
            _tokenCount,
            _status,
            _isLimitedToken,
            _active
        );
        return serviceCount;
    }


    /**
    * @dev Mints a token for public users.
    * @param _user The address of the user receiving the token.
    * @param _serviceId The ID of the service for which the token is minted.
    */
    function mintPublicToken(
        address _user,
        uint256 _serviceId
    ) 
        external 
        checkService(_serviceId, ServiceStatus.Public) 
    {
        _mintToken(_user, _serviceId);
    }  

    /**
    * @dev Mints a token for public users.
    * @param _user The address of the user receiving the token.
    * @param _serviceId The ID of the service for which the token is minted.
    */
    function mintPrivateToken(
        address _user,
        uint256 _serviceId
    ) 
        external onlyOwner 
        checkService(_serviceId, ServiceStatus.Private) 
    {
        _mintToken(_user, _serviceId);
    }

    function mintServiceToken(
        address _user,
        uint256 _serviceId
    ) 
        external 
        onlyManager(_serviceId) 
        checkService(_serviceId, ServiceStatus.Service) 
    {
        _mintToken(_user, _serviceId);
    }

    function mintPaidToken(
        address _user,
        uint256 _serviceId
    ) 
        external 
        payable 
        onlyManager(_serviceId) 
        checkService(_serviceId, ServiceStatus.Paid) 
    {
        require(services[_serviceId].price <= msg.value, JPSG_InsufficientFundsSent());

        uint256 contractFee = (msg.value * i_Transaction_Fee) / 100;
        uint256 managerAmount = msg.value - contractFee;

        _mintToken(_user, _serviceId);
        payable(msg.sender).transfer(managerAmount);
    }

    function mintWhitelistedToken(
        address _user,
        uint256 _serviceId
    ) 
        external 
        checkService(_serviceId, ServiceStatus.Whitelisted) 
    {
        require(isWhitelisted[_serviceId][_user], JPSG_NotWhitelisted());
        _mintToken(_user, _serviceId);
    }

    function _mintToken(
        address _user, 
        uint256 _serviceId
    ) private {
        if (services[_serviceId].isLimitedToken) {
            require(services[_serviceId].remainingTokens > 0, JPSG_TokenLimitExceeded());            
        }

        uint256 tokenId =  _mint(_user);
        services[_serviceId].remainingTokens -= 1;
        tokenIds[_user].push(tokenId);
        serviceIds[tokenId] = _serviceId;
        emit TokenMinted(_user, tokenId);
    }

    function tokenURI(uint256 _tokenId) public view override returns (string memory) {
        require(isValid(_tokenId), JPSG_InvalidTokenId());
        return services[serviceIds[_tokenId]].uri;
    }

    function revokeToken(
        address _user, 
        uint256 _tokenId
    ) 
        external 
        onlyManager(serviceIds[_tokenId])
    { 
        require(isValid(_tokenId), JPSG_InvalidTokenId());
        require(ownerOf(_tokenId) == _user, JPSG_NotTokenOwner());
        _revoke(_tokenId);
    }

    function withdraw() 
        external 
        onlyOwner
    {
        uint256 balance = address(this).balance;
        payable(msg.sender).transfer(balance);
    }   

    function fetchUserIDs(
        address _user,
        uint8 _start,
        uint8 _limit
    ) external view returns(uint256[] memory) {
        // return tokenIds[_user]; // Gas Intensive
        uint256[] memory ids = tokenIds[_user];
        uint256 end = _start + _limit > ids.length ? ids.length : _start + _limit;
        uint256[] memory result = new uint256[](end - _start);
        for (uint256 i = _start; i < end; i++) {
            result[i - _start] = ids[i];
        }
        return result;
    }

    function updateWhitelist(
        address _user,
        uint256 _serviceId,
        bool _status
    ) 
        external 
        onlyManager(_serviceId) 
        checkServiceID(_serviceId) 
        returns (bool) 
    {
        isWhitelisted[_serviceId][_user] = _status;
        return true;
    }

    function updateWhitelistBatch(
        address[] memory _users,
        uint256 _serviceId,
        bool _status
    ) 
        external 
        onlyManager(_serviceId) 
        checkServiceID(_serviceId) 
        returns (bool) 
    {
        for (uint256 i = 0; i < _users.length; i++)
            isWhitelisted[_serviceId][_users[i]] = _status;
        return true;
    }

    function updateServiceManager(
        address _manager,
        uint256 _serviceId
    ) external onlyOwner checkServiceID(_serviceId) {
        services[_serviceId].manager = _manager;
    }

    function updateServiceURI(
        string memory _uri,
        uint256 _serviceId
    ) external onlyManager(_serviceId) checkServiceID(_serviceId) nonEmptyURI(_uri) {
        services[_serviceId].uri = _uri;
    }

    function updateServiceRemainingTokens(
        uint256 _serviceId,
        uint64 _tokenCount
    ) external onlyManager(_serviceId) checkServiceID(_serviceId) {
        services[_serviceId].remainingTokens = _tokenCount;
    }

    function updateServiceActive(
        uint256 _serviceId,
        bool _active
    ) external onlyManager(_serviceId) checkServiceID(_serviceId) {
        services[_serviceId].active = _active;
    }

    function updateServicePrice(
        uint256 _serviceId,
        uint256 _price
    ) external onlyManager(_serviceId) checkServiceID(_serviceId) {
        services[_serviceId].price = _price;
    }
}

contracts/JPSMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

contract JPSMarketplace is 
    ERC721URIStorage, 
    Ownable, 
    ReentrancyGuard, 
    Pausable 
{

    // Errors
    error JPSM_SupplyExhausted();
    error JPSM_WalletLimitReached();
    error JPSM_RoyaltyPercentageExceeded();
    error JPSM_InsufficientPayment();
    error JPSM_InvalidParameters();
    error JPSM_Unauthorized();
    error JPSM_AuctionNotActive();
    error JPSM_PriceCalculationError();

    // Core variables
    uint256 private _tokenIds;
    uint256 public totalSupply;
    uint256 public maxPerWallet;
    address public feeRecipient;
    IERC20 public paymentToken; // Optional ERC20 payment support

    // Pricing constants
    uint256 public constant PRICE_PRECISION = 1e18;
    uint256 public constant FEE_PRECISION = 10000;

    // Dynamic pricing parameters
    struct PricingConfig {
        uint256 basePrice;
        uint256 demandMultiplier;
        uint256 scarcityMultiplier;
        uint256 timeDelayFactor;
        uint256 velocityFactor;        // New: Price adjustment based on sales velocity
        uint256 adjustmentInterval;
        uint256 lastAdjustmentTime;
        uint256 minPrice;             // Minimum price floor
        uint256 maxPrice;             // Maximum price ceiling
    }

    PricingConfig public pricingConfig;
    uint256 public marketplaceFee = 250; // 2.5%

    // Advanced token metadata
    enum Rarity { Common, Rare, Epic, Legendary }
    struct TokenData {
        Rarity rarity;
        uint256 royaltyPercentage;
        address royaltyRecipient;
        uint256 mintTime;
        uint256 lastSalePrice;
        uint256 saleCount;
        string category;
    }

    // Market structures
    struct Listing {
        uint256 tokenId;
        uint256 price;
        address seller;
        bool active;
        bool acceptsERC20;
        uint256 expiration;
    }

    struct Auction {
        uint256 tokenId;
        uint256 currentPrice;
        uint256 reservePrice;
        uint256 duration;
        uint256 startTime;
        uint256 lastBidTime;
        address highestBidder;
        uint256 highestBid;
        bool active;
        bool acceptsERC20;
        uint256 extensionTime; // Auction extension on late bids
    }

    struct PriceHistory {
        uint256 timestamp;
        uint256 price;
        uint256 supplyAtTime;
    }

    // Storage
    mapping(uint256 => TokenData) public tokenData;
    mapping(Rarity => uint256) public rarityMultipliers;
    mapping(address => uint256) public walletPurchases;
    mapping(uint256 => Listing) public listings;
    mapping(uint256 => Auction) public auctions;
    mapping(uint256 => PriceHistory[]) public priceHistory;
    mapping(address => uint256) public pendingWithdrawals;
    mapping(uint256 => uint256) public recentSalesVelocity; // Sales in last interval

    // Events
    event NFTMinted(uint256 indexed tokenId, address recipient, uint256 price, Rarity rarity);
    event PriceAdjusted(uint256 newBasePrice, uint256 timestamp);
    event Listed(uint256 indexed tokenId, uint256 price, address seller);
    event Purchased(uint256 indexed tokenId, address buyer, uint256 price);
    event AuctionStarted(uint256 indexed tokenId, uint256 startingPrice, uint256 duration);
    event BidPlaced(uint256 indexed tokenId, address bidder, uint256 amount);
    event AuctionExtended(uint256 indexed tokenId, uint256 newEndTime);
    event AuctionEnded(uint256 indexed tokenId, address winner, uint256 amount);

    constructor(
        uint256 _basePrice,
        uint256 _totalSupply,
        uint256 _maxPerWallet,
        address _feeRecipient,
        address _paymentToken // Optional ERC20 token address
    ) ERC721("JP Stacker Marketplace", "JPS") Ownable(msg.sender) {
        totalSupply = _totalSupply;
        maxPerWallet = _maxPerWallet;
        feeRecipient = _feeRecipient;
        paymentToken = IERC20(_paymentToken);

        pricingConfig = PricingConfig({
            basePrice: _basePrice,
            demandMultiplier: 150,      // 1.5x
            scarcityMultiplier: 200,    // 2x
            timeDelayFactor: 50,        // 0.5x
            velocityFactor: 100,        // 1x
            adjustmentInterval: 1 days,
            lastAdjustmentTime: block.timestamp,
            minPrice: _basePrice / 10,  // 10% of base
            maxPrice: _basePrice * 10   // 10x base
        });

        rarityMultipliers[Rarity.Common] = 100;
        rarityMultipliers[Rarity.Rare] = 150;
        rarityMultipliers[Rarity.Epic] = 300;
        rarityMultipliers[Rarity.Legendary] = 500;
    }

    // --- Advanced Dynamic Pricing ---

    function getCurrentPrice(Rarity _rarity) public view returns (uint256) {
        uint256 currentSupply = _tokenIds;
        if (currentSupply >= totalSupply) return pricingConfig.basePrice;

        // Demand factor based on current supply
        uint256 demandFactor = (currentSupply * pricingConfig.demandMultiplier * PRICE_PRECISION) / totalSupply;

        // Scarcity factor with protection against division by zero
        uint256 leftoverSupply = totalSupply - currentSupply;
        uint256 scarcityFactor = leftoverSupply > 0 
            ? (totalSupply * pricingConfig.scarcityMultiplier * PRICE_PRECISION) / leftoverSupply 
            : PRICE_PRECISION;

        // Time decay with velocity adjustment
        uint256 timeSinceLast = block.timestamp - pricingConfig.lastAdjustmentTime;
        uint256 decay = (timeSinceLast * pricingConfig.timeDelayFactor * pricingConfig.basePrice) / 
            (PRICE_PRECISION * 24 hours);
        uint256 velocityAdjustment = (recentSalesVelocity[block.timestamp / pricingConfig.adjustmentInterval] * 
            pricingConfig.velocityFactor * PRICE_PRECISION) / 100;

        uint256 timeAdjustedPrice = pricingConfig.basePrice > decay 
            ? pricingConfig.basePrice - decay + velocityAdjustment 
            : pricingConfig.basePrice + velocityAdjustment;

        // Combine factors with bounds checking
        uint256 dynamicPrice = timeAdjustedPrice * 
            (PRICE_PRECISION + demandFactor + scarcityFactor) / 
            PRICE_PRECISION;

        dynamicPrice = (dynamicPrice * rarityMultipliers[_rarity]) / 100;

        // Apply price bounds
        if (dynamicPrice < pricingConfig.minPrice) return pricingConfig.minPrice;
        if (dynamicPrice > pricingConfig.maxPrice) return pricingConfig.maxPrice;

        return dynamicPrice;
    }

    function updatePricingConfig(
        uint256 _demandMultiplier,
        uint256 _scarcityMultiplier,
        uint256 _timeDelayFactor,
        uint256 _velocityFactor
    ) external onlyOwner {
        pricingConfig.demandMultiplier = _demandMultiplier;
        pricingConfig.scarcityMultiplier = _scarcityMultiplier;
        pricingConfig.timeDelayFactor = _timeDelayFactor;
        pricingConfig.velocityFactor = _velocityFactor;
        pricingConfig.lastAdjustmentTime = block.timestamp;
        emit PriceAdjusted(pricingConfig.basePrice, block.timestamp);
    }

    // --- Minting ---

    function mintNFT(
        string memory _tokenURI,
        string memory _category,
        Rarity _rarity,
        uint256 _royaltyPercentage
    ) 
        external 
        payable 
        whenNotPaused 
        nonReentrant 
        returns (uint256) 
    {
        if (_tokenIds >= totalSupply) revert JPSM_SupplyExhausted();
        if (walletPurchases[msg.sender] >= maxPerWallet) revert JPSM_WalletLimitReached();
        if (_royaltyPercentage > 2500) revert JPSM_RoyaltyPercentageExceeded();

        uint256 price = getCurrentPrice(_rarity);
        if (msg.value <= price) revert JPSM_InsufficientPayment();

        _tokenIds++;

        _safeMint(msg.sender, _tokenIds);
        _setTokenURI(_tokenIds, _tokenURI);

        tokenData[_tokenIds] = TokenData({
            rarity: _rarity,
            royaltyPercentage: _royaltyPercentage,
            royaltyRecipient: msg.sender,
            mintTime: block.timestamp,
            lastSalePrice: price,
            saleCount: 1,
            category: _category
        });

        walletPurchases[msg.sender]++;
        pricingConfig.lastAdjustmentTime = block.timestamp;
        recentSalesVelocity[block.timestamp / pricingConfig.adjustmentInterval]++;

        priceHistory[_tokenIds].push(PriceHistory(block.timestamp, price, _tokenIds));

        if (msg.value > price) {
            _safeTransferETH(msg.sender, msg.value - price);
        }

        emit NFTMinted(_tokenIds, msg.sender, price, _rarity);
        return _tokenIds;
    }

    // --- Marketplace ---

    function listNFT(
        uint256 _tokenId,
        uint256 _price,
        bool _acceptsERC20,
        uint256 _duration
    ) 
        external 
        whenNotPaused 
    {
        if (ownerOf(_tokenId) != msg.sender) revert JPSM_Unauthorized();
        if (_price == 0 || _duration == 0) revert JPSM_InvalidParameters();
        if (listings[_tokenId].active || auctions[_tokenId].active) revert JPSM_InvalidParameters();

        _transfer(msg.sender, address(this), _tokenId);
        listings[_tokenId] = Listing({
            tokenId: _tokenId,
            price: _price,
            seller: msg.sender,
            active: true,
            acceptsERC20: _acceptsERC20,
            expiration: block.timestamp + _duration
        });

        emit Listed(_tokenId, _price, msg.sender);
    }

    function buyNFT(
        uint256 _tokenId, 
        bool _useERC20
    ) 
        external 
        payable 
        whenNotPaused 
        nonReentrant 
    {
        Listing memory listing = listings[_tokenId];
        if (!listing.active || block.timestamp > listing.expiration) revert JPSM_InvalidParameters();

        uint256 price = listing.price;
        _processPayment(listing, price, _useERC20);

        _processSale(_tokenId, msg.sender, price, listing.seller);
        emit Purchased(_tokenId, msg.sender, price);
    }

    // --- Auctions ---

    function startAuction(
        uint256 _tokenId,
        uint256 _reservePrice,
        uint256 _duration,
        bool _acceptsERC20,
        uint256 _extensionTime
    ) 
        external 
        whenNotPaused 
    {
        if (ownerOf(_tokenId) != msg.sender) revert JPSM_Unauthorized();
        if (_duration == 0 || _reservePrice == 0) revert JPSM_InvalidParameters();
        if (auctions[_tokenId].active || listings[_tokenId].active) revert JPSM_InvalidParameters();

        uint256 startPrice = getCurrentPrice(tokenData[_tokenId].rarity);
        _transfer(msg.sender, address(this), _tokenId);

        auctions[_tokenId] = Auction({
            tokenId: _tokenId,
            currentPrice: startPrice,
            reservePrice: _reservePrice,
            duration: _duration,
            startTime: block.timestamp,
            lastBidTime: 0,
            highestBidder: address(0),
            highestBid: 0,
            active: true,
            acceptsERC20: _acceptsERC20,
            extensionTime: _extensionTime
        });

        emit AuctionStarted(_tokenId, startPrice, _duration);
    }

    function placeBid(
        uint256 _tokenId, 
        bool _useERC20
    ) 
        external 
        payable 
        whenNotPaused 
        nonReentrant 
    {
        Auction storage auction = auctions[_tokenId];
        if (!auction.active) revert JPSM_AuctionNotActive();

        uint256 endTime = auction.startTime + auction.duration;
        if (block.timestamp >= endTime) revert JPSM_AuctionNotActive();

        uint256 minBid = auction.highestBid == 0 
            ? auction.currentPrice 
            : auction.highestBid + (auction.highestBid * 5) / 100; // 5% minimum increment

        _processPaymentForBid(auction, minBid, _useERC20);

        // Refund previous bidder
        if (auction.highestBidder != address(0)) {
            pendingWithdrawals[auction.highestBidder] += auction.highestBid;
        }

        // Extend auction if bid is in last 5 minutes
        if (endTime - block.timestamp < 5 minutes && auction.extensionTime > 0) {
            auction.duration += auction.extensionTime;
            emit AuctionExtended(_tokenId, endTime + auction.extensionTime);
        }

        auction.highestBidder = msg.sender;
        auction.highestBid = _useERC20 ? minBid : msg.value;
        auction.lastBidTime = block.timestamp;

        emit BidPlaced(_tokenId, msg.sender, auction.highestBid);
    }

    function endAuction(uint256 _tokenId) external nonReentrant {
        Auction storage auction = auctions[_tokenId];
        if (!auction.active) revert JPSM_AuctionNotActive();
        if (block.timestamp < auction.startTime + auction.duration && 
            msg.sender != owner() && 
            msg.sender != ownerOf(_tokenId)) 
            revert JPSM_AuctionNotActive();

        auction.active = false;
        if (auction.highestBid >= auction.reservePrice && auction.highestBidder != address(0)) {
            _processSale(_tokenId, auction.highestBidder, auction.highestBid, ownerOf(_tokenId));
            emit AuctionEnded(_tokenId, auction.highestBidder, auction.highestBid);
        } else {
            _transfer(address(this), ownerOf(_tokenId), _tokenId);
            emit AuctionEnded(_tokenId, address(0), 0);
        }
    }

    // --- Internal Functions ---

    function _processPayment(Listing memory _listing, uint256 _amount, bool _useERC20) internal {
        if (_useERC20) {
            if (!_listing.acceptsERC20) revert JPSM_InvalidParameters();
            if (paymentToken.transferFrom(msg.sender, address(this), _amount)) 
                revert JPSM_InsufficientPayment();
        } else {
            if (msg.value < _amount) revert JPSM_InsufficientPayment();
        }
    }

    function _processPaymentForBid(
        Auction memory _auction, 
        uint256 _amount, 
        bool _useERC20
    ) 
        internal 
    {
        if (_useERC20) {
            if (!_auction.acceptsERC20) revert JPSM_InvalidParameters();
            if (!paymentToken.transferFrom(msg.sender, address(this), _amount)) 
                revert JPSM_InsufficientPayment();
        } else {
            if (msg.value < _amount) revert JPSM_InsufficientPayment();
        }
    }

    function _processSale(
        uint256 _tokenId, 
        address _buyer, 
        uint256 _amount, 
        address _seller
    ) 
        internal 
    {
        TokenData storage data = tokenData[_tokenId];
        listings[_tokenId].active = false;

        uint256 royaltyAmount = (_amount * data.royaltyPercentage) / FEE_PRECISION;
        uint256 feeAmount = (_amount * marketplaceFee) / FEE_PRECISION;
        uint256 sellerAmount = _amount - royaltyAmount - feeAmount;

        _safeTransferETH(data.royaltyRecipient, royaltyAmount);
        _safeTransferETH(feeRecipient, feeAmount);
        _safeTransferETH(_seller, sellerAmount);

        _transfer(address(this), _buyer, _tokenId);

        data.lastSalePrice = _amount;
        data.saleCount++;
        priceHistory[_tokenId].push(PriceHistory(block.timestamp, _amount, _tokenIds));
        recentSalesVelocity[block.timestamp / pricingConfig.adjustmentInterval]++;

        if (msg.value > _amount) {
            _safeTransferETH(msg.sender, msg.value - _amount);
        }
    }

    function _safeTransferETH(address _to, uint256 _amount) internal {
        (bool success, ) = _to.call{value: _amount}("");
        require(success, "ETH transfer failed");
    }

    // --- Admin Functions ---

    function updateFee(uint256 _newFee) external onlyOwner {
        if (_newFee > 1000) revert JPSM_InvalidParameters(); // Max 10%
        marketplaceFee = _newFee;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // --- View Functions ---

    function getTokenDetails(uint256 _tokenId) external view returns (TokenData memory) {
        return tokenData[_tokenId];
    }

    function getPriceHistory(uint256 _tokenId) external view returns (PriceHistory[] memory) {
        return priceHistory[_tokenId];
    }

    function remainingSupply() external view returns (uint256) {
        return totalSupply - _tokenIds;
    }
}

contracts/StakingICO.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";

contract AdvancedStakingICO is ERC20, ERC20Burnable, Ownable, ReentrancyGuard, Pausable {

    // --- Token Configuration ---
    uint256 public constant TOTAL_SUPPLY = 1_000_000_000 * 10**18; // 1B tokens
    uint256 public constant ICO_ALLOCATION = 400_000_000 * 10**18; // 40% for ICO
    uint256 public constant STAKING_REWARDS = 300_000_000 * 10**18; // 30% for staking

    // --- Core Variables ---
    uint256 public icoEndTime;
    uint256 public totalStaked;
    uint256 public totalParticipants;
    address public nftContract;
    mapping(address => uint256) public userStakedAmount;
    mapping(address => uint256) public userLastUpdate;
    mapping(address => uint256) public userPendingRewards;

    // --- ICO Configuration ---
    uint256 public constant MIN_CONTRIBUTION = 0.1 ether;
    uint256 public constant MAX_CONTRIBUTION = 100 ether;
    uint256 public icoPrice = 0.0001 ether; // 1 token = 0.0001 ETH
    uint256 public totalRaised;
    bool public icoActive;

    // --- Staking Tiers ---
    enum StakingTier { Bronze, Silver, Gold, Platinum, Diamond }
    struct TierInfo {
        uint256 minStake;        // Minimum tokens to qualify
        uint256 rewardMultiplier; // Base reward multiplier (in basis points)
        uint256 lockPeriod;      // Minimum lock period in seconds
        uint256 maxStake;        // Maximum stake for this tier
        uint256 nftBoost;        // Additional boost % if holding specific NFT
    }

    mapping(StakingTier => TierInfo) public tiers;
    mapping(address => StakingTier) public userTier;

    // --- Advanced Staking Structures ---
    struct Stake {
        uint256 amount;
        uint256 startTime;
        uint256 lockPeriod;
        StakingTier tier;
        bool active;
        uint256 nftBoostId;     // Optional NFT boost
    }

    struct GovernanceProposal {
        uint256 id;
        string description;
        uint256 startTime;
        uint256 endTime;
        uint256 yesVotes;
        uint256 noVotes;
        bool executed;
        address proposer;
    }

    // --- Storage ---
    mapping(address => Stake[]) public userStakes;
    mapping(address => uint256) public userGovernancePower;
    mapping(uint256 => GovernanceProposal) public proposals;
    uint256 public proposalCount;
    mapping(address => mapping(uint256 => bool)) public hasVoted; // userAddress => proposalId => True/False

    // --- Dynamic Reward System ---
    uint256 public baseRewardRate = 50; // 0.5% daily base rate (in basis points)
    uint256 public rewardPool = STAKING_REWARDS;
    uint256 public rewardAdjustmentFactor; // Dynamic adjustment based on participation

    // --- Events ---
    event ICOContribution(address indexed contributor, uint256 amount, uint256 tokens);
    event Staked(address indexed user, uint256 amount, StakingTier tier, uint256 lockPeriod);
    event Unstaked(address indexed user, uint256 amount, uint256 reward);
    event RewardClaimed(address indexed user, uint256 amount);
    event ProposalCreated(uint256 indexed proposalId, address proposer, string description);
    event Voted(address indexed voter, uint256 proposalId, bool support);
    event ProposalExecuted(uint256 indexed proposalId);

    constructor(address _nftContract) 
        ERC20("JP Staking Token", "JPST")
        Ownable(msg.sender)
    {
        nftContract = _nftContract;
        _mint(address(this), TOTAL_SUPPLY);

        // Initialize staking tiers 
        // [Min tokens to qualify][Base reward multiplier][Min lock period][Maximum stake][Additional boost % if holding specific NFT]
        tiers[StakingTier.Bronze] = TierInfo(1000 * 10**18, 100, 30 days, 10000 * 10**18, 5);
        tiers[StakingTier.Silver] = TierInfo(10000 * 10**18, 125, 60 days, 50000 * 10**18, 10);
        tiers[StakingTier.Gold] = TierInfo(50000 * 10**18, 150, 90 days, 200000 * 10**18, 15);
        tiers[StakingTier.Platinum] = TierInfo(200000 * 10**18, 200, 180 days, 500000 * 10**18, 20);
        tiers[StakingTier.Diamond] = TierInfo(500000 * 10**18, 300, 365 days, TOTAL_SUPPLY, 30);

        icoActive = true;
        icoEndTime = block.timestamp + 30 days;
    }

    // --- ICO Functions ---

    function contribute() 
        external 
        payable 
        whenNotPaused 
        nonReentrant 
    {
        require(icoActive && block.timestamp <= icoEndTime, "ICO not active");
        require(msg.value >= MIN_CONTRIBUTION && msg.value <= MAX_CONTRIBUTION, "Invalid contribution");

        uint256 tokens = (msg.value * 10**18) / icoPrice;
        require(totalRaised + tokens <= ICO_ALLOCATION, "ICO allocation exceeded");

        totalRaised += tokens;
        totalParticipants++;
        _transfer(address(this), msg.sender, tokens);

        emit ICOContribution(msg.sender, msg.value, tokens);
    }

    function endICO() external onlyOwner {
        require(icoActive, "ICO already ended");
        icoActive = false;
        icoEndTime = block.timestamp;

        // Burn unsold ICO tokens
        uint256 unsold = ICO_ALLOCATION - totalRaised;
        if (unsold > 0) {
            _burn(address(this), unsold);
        }
    }

    // --- Staking Functions ---

    function stake(
        uint256 _amount, 
        uint256 _lockPeriod, 
        uint256 _nftId
    ) 
        external 
        whenNotPaused 
        nonReentrant 
    {
        require(_amount > 0, "Invalid amount");
        require(balanceOf(msg.sender) >= _amount, "Insufficient balance");

        StakingTier tier = _determineTier(_amount);
        require(_lockPeriod >= tiers[tier].lockPeriod, "Lock period too short");
        require(_amount <= tiers[tier].maxStake, "Exceeds tier max stake");

        // NFT boost validation
        uint256 nftBoost = 0;
        if (_nftId > 0 && IERC721(nftContract).ownerOf(_nftId) == msg.sender) {
            nftBoost = tiers[tier].nftBoost;
        }

        _transfer(msg.sender, address(this), _amount);
        totalStaked += _amount;

        userStakes[msg.sender].push(Stake({
            amount: _amount,
            startTime: block.timestamp,
            lockPeriod: _lockPeriod,
            tier: tier,
            active: true,
            nftBoostId: _nftId
        }));

        userStakedAmount[msg.sender] += _amount;
        userLastUpdate[msg.sender] = block.timestamp;
        userTier[msg.sender] = tier;
        userGovernancePower[msg.sender] += _amount;

        _updateRewardAdjustment();
        emit Staked(msg.sender, _amount, tier, _lockPeriod);
    }

    function unstake(
        uint256 _stakeIndex
    ) 
        external 
        nonReentrant 
    {
        Stake storage _stake = userStakes[msg.sender][_stakeIndex];
        require(_stake.active, "Stake not active");
        require(block.timestamp >= _stake.startTime + _stake.lockPeriod, "Lock period not ended");

        uint256 reward = calculateReward(msg.sender, _stakeIndex);

        require(rewardPool >= reward, "Insufficient reward pool");

        _stake.active = false;
        totalStaked -= _stake.amount;
        rewardPool -= reward;
        userStakedAmount[msg.sender] -= _stake.amount;
        userGovernancePower[msg.sender] -= _stake.amount;

        _transfer(address(this), msg.sender, _stake.amount);
        if (reward > 0) {
            _mint(msg.sender, reward);
        }

        _updateRewardAdjustment();
        emit Unstaked(msg.sender, _stake.amount, reward);
    }

    function claimRewards() external nonReentrant {
        uint256 totalReward = 0;
        for (uint256 i = 0; i < userStakes[msg.sender].length; i++) {
            if (userStakes[msg.sender][i].active) {
                totalReward += calculateReward(msg.sender, i);
            }
        }

        require(totalReward > 0, "No rewards to claim");
        require(rewardPool >= totalReward, "Insufficient reward pool");

        rewardPool -= totalReward;
        userLastUpdate[msg.sender] = block.timestamp;
        _mint(msg.sender, totalReward);

        emit RewardClaimed(msg.sender, totalReward);
    }

    // --- Governance Functions ---

    function createProposal(
        string memory _description
    ) external {
        require(userStakedAmount[msg.sender] >= 10000 * 10**18, "Insufficient stake for proposal");

        proposalCount++;
        proposals[proposalCount] = GovernanceProposal({
            id: proposalCount,
            description: _description,
            startTime: block.timestamp,
            endTime: block.timestamp + 7 days,
            yesVotes: 0,
            noVotes: 0,
            executed: false,
            proposer: msg.sender
        });

        emit ProposalCreated(proposalCount, msg.sender, _description);
    }

    function vote(uint256 _proposalId, bool _support) external {
        GovernanceProposal storage proposal = proposals[_proposalId];
        require(block.timestamp >= proposal.startTime && block.timestamp <= proposal.endTime, "Voting not active");
        require(!hasVoted[msg.sender][_proposalId], "Already voted");
        require(userGovernancePower[msg.sender] > 0, "No voting power");

        hasVoted[msg.sender][_proposalId] = true;
        if (_support) {
            proposal.yesVotes += userGovernancePower[msg.sender];
        } else {
            proposal.noVotes += userGovernancePower[msg.sender];
        }

        emit Voted(msg.sender, _proposalId, _support);
    }

    function executeProposal(uint256 _proposalId) external onlyOwner {
        GovernanceProposal storage proposal = proposals[_proposalId];
        require(block.timestamp > proposal.endTime, "Voting not ended");
        require(!proposal.executed, "Already executed");
        require(proposal.yesVotes > proposal.noVotes, "Proposal not approved");

        proposal.executed = true;
        // Implementation of proposal execution would depend on specific governance actions
        emit ProposalExecuted(_proposalId);
    }

    // --- Internal Functions ---

    function _determineTier(uint256 _amount) internal view returns (StakingTier) {
        if (_amount >= tiers[StakingTier.Diamond].minStake) return StakingTier.Diamond;
        if (_amount >= tiers[StakingTier.Platinum].minStake) return StakingTier.Platinum;
        if (_amount >= tiers[StakingTier.Gold].minStake) return StakingTier.Gold;
        if (_amount >= tiers[StakingTier.Silver].minStake) return StakingTier.Silver;
        return StakingTier.Bronze;
    }

    function calculateReward(address _user, uint256 _stakeIndex) public view returns (uint256) {
        Stake memory _stake = userStakes[_user][_stakeIndex];
        if (!_stake.active) return 0;

        uint256 timeElapsed = block.timestamp - userLastUpdate[_user];
        // uint256 baseReward = _stake.amount.mul(baseRewardRate).mul(timeElapsed).div(1 days).div(10000); // Basis points
        uint256 baseReward = (_stake.amount * baseRewardRate * timeElapsed) / (1 days * 10000);         

        uint256 tierMultiplier = tiers[_stake.tier].rewardMultiplier;
        uint256 nftBoost = _stake.nftBoostId > 0 ? tiers[_stake.tier].nftBoost : 0;

        return (baseReward * (tierMultiplier + nftBoost) * rewardAdjustmentFactor) / 10000;

    }

    function _updateRewardAdjustment() internal {
        if (totalStaked > 0) {
            rewardAdjustmentFactor = (TOTAL_SUPPLY * 10000) / totalStaked;
            if (rewardAdjustmentFactor > 20000) rewardAdjustmentFactor = 20000; // Cap at 2x
            if (rewardAdjustmentFactor < 5000) rewardAdjustmentFactor = 5000;   // Floor at 0.5x
        }
    }

    // --- Admin Functions ---

    function updateBaseRewardRate(uint256 _newRate) external onlyOwner {
        require(_newRate <= 1000, "Rate too high"); // Max 10%
        baseRewardRate = _newRate;
    }

    function withdrawFunds() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No funds to withdraw");
        payable(owner()).transfer(balance);
    }

    // --- View Functions ---

    function getUserStakes(address _user) external view returns (Stake[] memory) {
        return userStakes[_user];
    }

    function getTotalRewards(address _user) external view returns (uint256) {
        uint256 total = 0;
        for (uint256 i = 0; i < userStakes[_user].length; i++) {
            if (userStakes[_user][i].active) {
                total = total + calculateReward(_user, i);
            }
        }
        return total;
    }
}

